"""Training-only reset curriculum generated by an existing RL route policy.

Traffic time, actuator state, wind forcing, prior clearance and every mission
gate are carried through the prefix. Evaluation always uses the original spawn.
"""
import numpy as np
from .coupled_overtaking_v7 import CoupledOvertakingEnv,TRAFFIC_PATH
from .traffic_lane import NumpyActor
from .environment import CONFIG
from .plant import ROOT

PREFIX='reports/artifacts/mission_rl_v1/overtaking_constrained_04/actor.json'
class CoherentCurriculumEnv(CoupledOvertakingEnv):
 def __init__(self,*args,**kwargs):
  self.prefix_actor=NumpyActor(ROOT/PREFIX)
  super().__init__(*args,**kwargs)
 def reset(self,*,seed=None,options=None):
  obs,info=super().reset(seed=seed,options=options)
  if self.split!='train' or self.rng.random()>.65:return obs,info
  count=int(self.rng.integers(35,81))
  for _ in range(count):
   physical=self.prefix_actor.command(obs)
   raw=2*(physical-self.prefix_actor.lo)/(self.prefix_actor.hi-self.prefix_actor.lo)-1
   obs,_,term,trunc,info=CoupledOvertakingEnv.step(self,raw)
   if term or trunc:return super().reset(options=options)
  self.curriculum=True;self.initial_waypoint=self.waypoint;self.reward_sum=0.
  return self.observation(),{}

def main():
 import train_mission_rl as trainer
 from train_mission_rl import sha
 trainer.MissionEnv=CoherentCurriculumEnv
 trainer.CONFIG={**CONFIG,'reward_profile':'two_vessel_coherent_curriculum_v9','action_high':[1.,.65],
  'restart_exploration':True,'policy_replay_warmup_steps':2000,'reinitialize_critic':True,
  'traffic_policy_path':TRAFFIC_PATH,'traffic_policy_sha256':sha(ROOT/TRAFFIC_PATH),
  'curriculum_policy_path':PREFIX,'curriculum_policy_sha256':sha(ROOT/PREFIX)}
 trainer.main()
if __name__=='__main__':main()
